/*
 * WHAT ONE LESSON IS WRITTEN AGAINST (TASK-L189 §3).
 *
 * The two-document model, served to the trainer's Claude: the learner's project
 * (name, problem statement, every saved answer) and the concept's canonical body
 * — the teaching, written generically, which a lesson projects onto THIS project.
 * CONCEPT_BODIES is generated from the product's corpus.
 *
 * It also names the capture fields their other lessons already ask for, so a new
 * lesson does not overwrite an answer, and the learners with a published lesson
 * on this concept, which copyLesson can start from.
 */
/* TRAINER_DOOR_LIB:begin — GENERATED by tools/build-trainer-door.mjs, do not hand-edit */
/*
 * THE RULES THE TRAINER'S TOOLS SHARE (TASK-L189). The ONE source of them.
 *
 * tools/build-trainer-door.mjs copies this file, byte for byte, between the
 * TRAINER_DOOR_LIB markers of every function the trainer's Claude reaches, and
 * tools/check-trainer-door.mjs fails when any copy differs. Seven functions
 * would otherwise spell "their live path", "a field another lesson asks for"
 * and "still about the other learner's project" seven times, and two spellings
 * of one rule is how they start to disagree.
 *
 * It is a plain script, not a module: a cloud Function's script is one string,
 * evaluated with `Noodl` in scope, and cannot import. Everything it defines
 * hangs off one constant, `DOOR`.
 *
 * Every read is `{ plain: true }` (NodeGX HLT-022). Nothing here writes.
 */
const DOOR = (() => {
  const R = Noodl.Records;
  const q = (c, where, limit) => R.query(c, where, { limit: limit || 1000, plain: true });
  const blank = (x) => x === undefined || x === null || x === '';
  const newestFirst = (rows) => [...rows].sort((a, b) => (String(a.createdAt || '') < String(b.createdAt || '') ? 1 : -1));

  /** The caller's address, for `updatedByEmail`. From the session's account, never an argument. */
  async function callerEmail(callerId) {
    if (blank(callerId)) return null;
    const u = await q('_User', { objectId: { equalTo: String(callerId) } }, 2);
    return u.length === 1 ? String(u[0].username || u[0].email || '').trim().toLowerCase() || null : null;
  }

  /** A learner: their profile, their project, and the name their coach knows them by. Null when there is none. */
  async function learner(learnerId) {
    const id = String(learnerId || '').trim();
    if (!id) return null;
    const profiles = await q('LearnerProfile', { learnerId: { equalTo: id } }, 2);
    if (profiles.length !== 1) return null;
    const [contexts, invites] = await Promise.all([
      q('ProjectContext', { learnerId: { equalTo: id } }, 2),
      q('LearnerInvite', { claimedByLearnerId: { equalTo: id } })
    ]);
    const ctx = contexts[0] || null;
    const label = newestFirst(invites).map((i) => i.label).find((l) => typeof l === 'string' && l.trim());
    return {
      learnerId: id,
      // The coach's own shorthand, then the project's name, then the id. Never the
      // email address: the trainer's Claude is a model run by Anthropic, and the
      // address is not something a lesson needs (sprint 55 §5).
      name: (label && label.trim()) || (ctx && ctx.projectName) || id,
      ctx
    };
  }

  /** Their live path — the newest — and its live steps in order. The `lesson` read's rule. */
  async function livePath(learnerId) {
    const paths = await q('LearningPath', { learnerId: { equalTo: String(learnerId) } });
    const live = newestFirst(paths)[0];
    if (!live) return { path: null, steps: [] };
    const steps = (await q('PathStep', { pathId: { equalTo: live.pathId } }))
      .filter((s) => blank(s.removedAt))
      .sort((a, b) => a.position - b.position);
    return { path: live, steps };
  }

  /** The step for a concept, or a sentence saying where it could go instead. */
  function stepFor(steps, conceptId, who) {
    const step = steps.find((s) => s.conceptId === conceptId);
    if (step) return { step };
    const on = steps.map((s) => s.conceptId).join(', ');
    return {
      why: '"' + conceptId + '" is not on ' + who + "'s path. A lesson is written for a step they have. " +
        (on ? 'Their path is: ' + on + '. ' : 'They have no path yet. ') +
        'To add it, set their path first with setLearnerPath.'
    };
  }

  /** The capture fields a lesson asks for: capture sections, and activities that capture a fact. */
  function fieldsOf(lesson) {
    const out = [];
    for (const s of (lesson && lesson.sections) || []) {
      if (s && s.kind === 'capture' && s.field) out.push(String(s.field));
      if (s && s.kind === 'activity' && s.capturesProjectFact && s.capturesProjectFact.field) out.push(String(s.capturesProjectFact.field));
    }
    return out;
  }

  /** Newest published lesson per concept for one learner. */
  async function published(learnerId) {
    const rows = await q('Lesson', { learnerId: { equalTo: String(learnerId) } });
    const best = {};
    for (const r of rows) if (!best[r.conceptId] || (r.generationVersion || 0) > (best[r.conceptId].generationVersion || 0)) best[r.conceptId] = r;
    return best;
  }

  async function drafts(learnerId) {
    const rows = await q('LessonDraft', { learnerId: { equalTo: String(learnerId) } });
    const by = {};
    for (const r of rows) by[r.conceptId] = r;
    return by;
  }

  /**
   * Every capture field their OTHER lessons (published or drafted) ask for, by
   * field. Two lessons writing one fact means the second answer silently replaces
   * the first on their project (check-lessons' rule, enforced at the write).
   */
  async function fieldsElsewhere(learnerId, conceptId) {
    const [pub, dr] = await Promise.all([published(learnerId), drafts(learnerId)]);
    const map = {};
    for (const src of [pub, dr]) {
      for (const [c, lesson] of Object.entries(src)) {
        if (c === conceptId) continue;
        for (const f of fieldsOf(lesson)) if (!map[f]) map[f] = c;
      }
    }
    return map;
  }

  function fieldClash(lesson, elsewhere) {
    const clash = fieldsOf(lesson).filter((f) => elsewhere[f]);
    if (!clash.length) return null;
    return 'Their lesson on ' + clash.map((f) => '"' + elsewhere[f] + '" already asks for "' + f + '"').join('; ') +
      '. Two lessons saving one answer would overwrite it. Give this capture a different field name.';
  }

  /**
   * THE PRODUCT'S GATE (validateLessonOutput, compiled from its source into
   * LESSON_GATE). Answers the lesson as the gate returned it, or every problem
   * as `path: message` — never a raw ZodError, which a model reads as noise.
   */
  function gate(lesson) {
    if (typeof LessonGate === 'undefined') throw new Error('this function carries no LESSON_GATE block');
    try {
      const v = LessonGate.validateLessonOutput(lesson);
      return { lesson: { title: v.title, hook: v.hook, landing: v.landing, steps: v.steps, sections: v.sections } };
    } catch (e) {
      const issues = e && Array.isArray(e.issues)
        ? e.issues.map((i) => (i.path && i.path.length ? i.path.join('.') : '(the lesson)') + ': ' + i.message)
        : [String((e && e.message) || e)];
      return { problems: issues };
    }
  }

  function refusalFor(problems) {
    return 'The lesson does not pass the course\'s lesson check, so nothing was saved. Fix these and send it again:\n- ' +
      problems.slice(0, 25).join('\n- ') + (problems.length > 25 ? '\n- …and ' + (problems.length - 25) + ' more.' : '');
  }

  /**
   * STILL ABOUT THE OTHER LEARNER'S PROJECT (sprint 55 §4).
   *
   * The terms are the source learner's project name, problem statement and every
   * saved answer at least 12 characters long, trimmed, case-insensitive — minus any
   * that also appear in the target's own project, because a phrase both projects
   * share is not a leak. A place "mentions" a term when any string in it contains it.
   */
  function leakTerms(sourceCtx, targetCtx) {
    const texts = (ctx) => {
      if (!ctx) return [];
      const facts = ctx.facts && typeof ctx.facts === 'object' ? Object.values(ctx.facts) : [];
      return [ctx.projectName, ctx.problemStatement, ...facts].filter((x) => x !== undefined && x !== null).map((x) => String(x).trim());
    };
    const theirs = texts(targetCtx).join('\n').toLowerCase();
    const terms = [];
    for (const t of texts(sourceCtx)) {
      const isName = sourceCtx && t === String(sourceCtx.projectName || '').trim();
      if (!t || (!isName && t.length < 12)) continue;
      if (theirs.includes(t.toLowerCase())) continue;
      if (!terms.some((x) => x.toLowerCase() === t.toLowerCase())) terms.push(t);
    }
    return terms;
  }

  function strings(x, out) {
    if (typeof x === 'string') out.push(x);
    else if (Array.isArray(x)) x.forEach((y) => strings(y, out));
    else if (x && typeof x === 'object') Object.values(x).forEach((y) => strings(y, out));
    return out;
  }

  function mentions(lesson, terms) {
    if (!terms.length || !lesson) return [];
    const places = [['title', lesson.title], ['hook', lesson.hook], ['landing', lesson.landing]];
    for (const s of lesson.steps || []) places.push(['step ' + s.id, s]);
    for (const s of lesson.sections || []) places.push(['section ' + s.id, s]);
    const found = [];
    for (const [where, value] of places) {
      const hay = strings(value, []).join('\n').toLowerCase();
      for (const term of terms) if (hay.includes(term.toLowerCase())) found.push({ term, where });
    }
    return found;
  }

  function previewPath(learnerId, conceptId, which) {
    return '/preview?learner=' + encodeURIComponent(learnerId) + '&concept=' + encodeURIComponent(conceptId) + (which ? '&which=' + which : '');
  }

  return { q, blank, newestFirst, callerEmail, learner, livePath, stepFor, fieldsOf, published, drafts, fieldsElsewhere, fieldClash, gate, refusalFor, leakTerms, mentions, previewPath };
})();
/* TRAINER_DOOR_LIB:end */
/* CONCEPT_BODIES:begin — GENERATED by tools/build-trainer-door.mjs, do not hand-edit */
const CONCEPT_BODIES = {"what-the-web-is":{"title":"What the web actually is","capsule":"A web app is a conversation between software running in your browser and software running on a computer far away. Your browser sends a request; a server sends back a response; your browser paints the result. Understanding this one picture — the request and the response — is the mental model everything else in web development sits on.","canonicalBody":"A web app is a conversation between two programs: one running in your browser, one running on a computer you never see. When you type a URL and press Enter, your browser sends a request — a message asking for something. A server on the other end receives that request, prepares a response, and sends it back. Your browser takes that response and draws the page. Every web page, every login, every time you click a button that saves something: all of it is that same exchange. Request, then response.\n\nThe reason this picture matters is that it tells you where things are. \"The web\" is not one place — it is a wire between your browser (which runs on your device, which you own) and a server (which runs somewhere else, which someone else runs). Anything that lives only in your browser disappears when you close the tab and is invisible to everyone else. Anything that lives on a server stays put and is reachable by anyone the server allows. Every architectural question you will face — do I need a backend, where does data go, why does this work for me but not for someone else — starts with this picture.\n\nWhen you are building with AI, you describe what you want to happen and Claude Code (or your own AI assistant) writes the code. But to give useful instructions and to check that the result makes sense, you need to be able to say which side of the wire each piece belongs on. \"This part runs in the browser\" or \"this part runs on a server\" — because the model will assume you know, and will write code that crosses the wire without explaining that it does.\n\nThe thing to watch for: the model often generates code that conflates the two sides — browser code that silently depends on a server-side variable, or server logic tucked into a frontend file without explanation. Any time the model hands you code that fetches data, stores something, or talks to an external service, ask: is this running in the browser or on a server, and where does the data actually go? If you cannot answer that from reading the code, ask before you ship.","prerequisites":[]},"git-tracking-your-work":{"title":"Git: tracking your work — and why it matters more with AI","capsule":"Git snapshots your code over time; GitHub is where those snapshots live online — the Google Drive for software. Each commit is a save-point you can return to. With AI making many changes fast, snapshots are how you tell what changed and undo what broke. Commit after each finished chunk, not every few seconds.","canonicalBody":"Git is the tool developers use to take snapshots of their code over time. Each snapshot — called a commit — records the exact state of every tracked file at that moment, along with who made the change, when, and a message explaining why. GitHub (and its siblings GitLab and Bitbucket) is where those snapshots live online: think of it as the Google Drive for software — the place your work is saved somewhere that isn't just your laptop, where you can get it back if your machine dies, share it with others, and where almost every hosting platform expects your code to be before it will deploy it. Git is the tracking; GitHub is the somewhere-safe.\n\nThe mental model that matters is the save-point. Before cloud autosave, you saved a Word document by hand — and you did not hit save every ten seconds. You saved after finishing a meaningful chunk: a section written, a table laid out, a draft you would not want to lose. A commit is the same instinct. You commit when you have completed something worth keeping — a feature that works, a bug fixed, a layout you are happy with — and you give it a label that means something later. Each commit is a clearly-marked point you can return to: \"this is where I go back to so I don't lose much work, but I also get rid of that design change the model made two commits ago.\" That is the whole value — a trail of labelled points you can roll back to, not a frantic stream of saves.\n\nGit integrates well with AI-assisted workflows. Claude Code (or your own AI assistant) can help write commit messages, explain what changed in a diff, generate a `.gitignore` for your project type, or suggest a branching approach for a new feature. What remains yours is the judgment about *when* to commit and *why*. The model can describe what changed; only you know why a decision was made. Write the why in your messages — not just \"update CSS\" but \"increase button padding for better mobile tap targets,\" or \"fix: orders were including cancelled items because the filter condition was inverted.\" Commit messages are project memory, and project memory compounds.\n\nThere are two AI-specific failure modes, and they pull in opposite directions. The first is under-snapshotting: the model does not prompt you to commit before it starts changing things, so an uninterrupted session of AI edits can leave you hours of work away from your last clean save-point. Before asking the model to do anything substantial — a refactor, a new feature, a significant change to existing logic — commit the current state first, so you have something to roll back to. The second is the opposite, and it is the one nobody warns you about: many AI coding tools commit constantly, automatically, after every tiny change. Leave that unchecked and a two-week prototype ends up with two thousand commits — which looks ridiculous and, worse, is useless, because when every change is its own commit there are no meaningful points to roll back to. The skill is the same in both cases: you own committing at meaningful, completed, clearly-labelled points — not the model's instinct to snapshot everything or nothing. If your tool auto-commits, learn how to squash a run of tiny commits back into one labelled save-point, or turn the behaviour off and commit deliberately yourself.","prerequisites":[]},"frontend-and-backend":{"title":"Frontend and backend: who does what","capsule":"The frontend is the code that runs in your browser — what you see and click. The backend is the code that runs on a server — the logic and data that survive after you close the tab. Every web app has both. Understanding which side owns which job is the starting map for building anything on the web.","canonicalBody":"The frontend is the part of a web app that runs in your browser — the page you see, the buttons you click, the form that validates your input before submitting. The backend is the part that runs on a server — the logic that processes your request, the database that stores the data, the rules that are enforced whether or not anyone is watching. Most web apps have both sides, and they communicate over the network: the frontend asks, the backend answers.\n\nThe distinction matters because the two sides have different capabilities and different levels of trust. The frontend is convenient — it is close to the user and can respond immediately — but it is untrustworthy: anyone can open their browser's developer tools and modify what it does. Anything that must be enforced — price calculations, permission checks, data validation — must live on the backend, where your code runs and the user cannot touch it. The frontend shows things and gathers input; it cannot be the place where decisions that matter are made.\n\nWhen you describe a feature to Claude Code (or your own AI assistant), naming which side it belongs on produces better code. \"Show the user their order total\" is a frontend task. \"Calculate the order total from the database and return it\" is a backend task. The model will usually infer correctly, but when it guesses wrong it produces code that looks right and behaves unexpectedly. The habit is: for every feature, say whether it is display (frontend) or logic and storage (backend), and the model will place the code on the correct side.\n\nThe most common AI-generated mistake here is frontend code that assumes data is \"just there\" — a JavaScript function that reads a variable the model forgot to explain how to populate, or a component that calculates a price in the browser (where a user could manipulate it) instead of fetching it from a server (where they cannot). When you review generated code, check where the data comes from. If a value that affects what the user can do is calculated entirely in the browser, ask whether that calculation should happen on the backend instead.","prerequisites":["what-the-web-is"]},"what-is-a-backend":{"title":"What a backend is, and when you actually need one","capsule":"A backend is a program running on a computer you never sit in front of, so your data and logic survive after you close the browser and can be shared between people. You need one the moment more than one person must see the same data, or the data has to outlive a single browser session — not before.","canonicalBody":"A backend is a program that runs on a computer you never sit in front of — a machine in a data centre somewhere — instead of inside your web browser. That sounds abstract, so here is the practical difference it makes. Anything that lives only in your browser disappears when you close the tab, and only you can see it. Anything that lives in a backend stays put after you leave, and other people can reach it too.\n\nFor a long time you do not need one. A tool that takes something you already have, transforms it, and hands it straight back to you can live entirely in the browser. It is faster to build, cheaper to run, and there is no server to look after. Reach for a backend only when you hit one of two walls.\n\nThe first wall is sharing. The moment a second person has to see or change the same data, that data can no longer live in your browser — your browser is yours alone. It has to live somewhere both of you can reach, and that shared place is a backend.\n\nThe second wall is permanence. If the work has to survive being closed — a record that must still be there tomorrow, a list that grows over weeks — it cannot depend on a single browser session. A backend is the thing that remembers.\n\nThere is a real cost to crossing either wall. A backend is another moving part: it has to be hosted, kept running, secured, and paid for. So the honest rule is not \"always build a backend\" and not \"never build one\". It is this: stay in the browser until sharing or permanence forces your hand, then add the smallest backend that solves the specific wall you hit. Cross too early and you buy complexity you do not need; cross too late and you rebuild. The skill is noticing which wall you are actually standing in front of.\n\nOnce you know which wall you have hit, Claude Code (or your own AI assistant) does most of the building. Tell it what happened: people need to share data, or the data has to survive being closed. It can scaffold the server, set up the routes, and wire up the database — fast, and it is good at this part. What stays yours is the judgment that got you there: whether you have actually hit a wall, and which one. The model cannot make that call. It will not ask. Once the backend exists, check it the way you check anything else. Call the route yourself. Look at what comes back. Confirm the data is still there next time you open the tab.\n\nAsk for a backend and you will get one, whether or not you needed it. Most of what the model has seen assumes a real project has a server and a database. Left alone, it will often build a full backend for a task a browser-only tool would have solved — a calculator, a checklist, anything that never needed to be shared or to outlive a tab. You then own everything that comes with it: hosting, secrets, a deployment you did not ask for. Before you accept a backend, say this: \"Can this work entirely in the browser? If not, tell me exactly which part forces a server.\"","prerequisites":["frontend-and-backend"]},"what-an-api-is":{"title":"What an API is: borrowing another thing's superpower","capsule":"An API is the agreed-upon way one piece of software asks another to do something. Every time an app processes a payment, sends an email, shows a map, or logs in with an external account, it is using an API. You rarely build these capabilities from scratch — you borrow them through a defined interface and pay for usage.","canonicalBody":"An API is the agreed-upon way one piece of software asks another piece of software to do something. When an app shows a map, it calls an API that a mapping company built — sending a request in a format they defined, and receiving a response in a format they promise to maintain. The app is not copying map data or replicating the routing algorithm; it is borrowing that capability through the interface. The same pattern applies to payments, email delivery, SMS, authentication with external accounts, address validation, currency conversion: almost every useful capability that already exists somewhere is exposed through an API.\n\nUnderstanding APIs changes what you think your app has to contain. You do not need to build a payment system — the major providers built one and expose it as an API. You do not need to build email delivery. The real skill is knowing what exists, how to call it, and what it costs. Almost every production web app is mostly orchestration of other APIs, not novel code, and the economic logic is straightforward: access a capability that took years and millions to build, in exchange for following the interface rules and paying a usage fee.\n\nClaude Code (or your own AI assistant) is extremely good at writing API calls. You describe the intent — \"send a welcome email when a user signs up, using this email service's API\" — and the model writes the fetch call, the headers, the request body shape, and often the error handling. What you supply is the intent, the constraints (which provider, what credentials you have), and what should happen if the call fails. What you then do is run the code, look at what comes back, and confirm it matches what you expected.\n\nThere are three things the model almost never includes unless you ask: authentication (how the API verifies you are allowed to call it — API keys that go in headers, OAuth tokens that expire), rate limits (the maximum number of calls per hour or day, and what your app should do when it exceeds them), and error handling (what happens when the API is temporarily down, returns a shape you did not expect, or rejects the request with an error code). Specify these before you write any API call. \"What happens if this call fails?\" is the question to ask before you merge the code — not after the first production incident.","prerequisites":["frontend-and-backend"]},"html-the-structure":{"title":"HTML: the structure of every page","capsule":"HTML is the language that names the parts of a web page — headings, paragraphs, links, buttons, images. It describes what is on the page, not how it looks. Every page starts as HTML. You rarely write it by hand, but you need to read it — structure errors are invisible to the eye and have real consequences for accessibility.","canonicalBody":"HTML is the language that names the parts of a web page. It tells the browser: this is a heading, this is a paragraph, this is a link, this is a button, this is an image. HTML does not control how anything looks — that is CSS — and it does not make anything interactive — that is JavaScript. It is purely structure: a description of what exists on the page and what each thing is. Every web page starts as HTML; everything built on top of it — styles, interactivity, search engine indexing, screen reader navigation — depends on the structure being correct.\n\nHTML matters to you not because you will write it by hand, but because its correctness has real consequences you cannot see by looking at the rendered page. A button that is actually a `<div>` styled to look like a button responds to a mouse click but cannot be activated by pressing the space bar — which means keyboard users and screen reader users cannot use it. An image without an `alt` attribute is invisible to anyone using a screen reader and conveys nothing to search engines. The wrong heading level — an `h3` used because it looks the right size rather than because it is the third level of a hierarchy — breaks the document structure that assistive technology relies on to navigate a page. These are invisible problems in the visual browser test and real problems in the world.\n\nClaude Code (or your own AI assistant) writes HTML quickly and usually correctly. You describe the page: \"a sign-up form with a name field, an email field, and a submit button; a heading above it.\" The model produces the HTML. What you supply is the intent and the content. What you then do is open it in a browser, check that it looks right, and then tab through it with a keyboard — every interactive element (links, buttons, inputs) should receive focus in a logical order and be usable without a mouse. This takes two minutes and catches the most common structural problems.\n\nAI-generated HTML is usually syntactically valid and often semantically wrong. Three things to check specifically: heading order — do headings go `h1` then `h2` then `h3`? The model frequently uses heading levels for visual size rather than document hierarchy. Form labels — every input should have a matching `<label>` element that describes it; the model often uses placeholder text inside the input instead, which disappears when you type and provides no label for screen readers. Alt text on images — either a real description of what the image shows, or explicitly `alt=\"\"` for purely decorative images. None of these are visible mistakes in a quick browser check, which is exactly why they get shipped.","prerequisites":["frontend-and-backend"]},"endpoints-and-requests":{"title":"Endpoints and requests: the address and the envelope","capsule":"An endpoint is a specific address on a server that does one defined thing. A request is the envelope you send to it: the address, a method (GET to fetch, POST to send data), and optionally a payload. These two ideas — address and method — are the grammar of every API call you will ever make or build.","canonicalBody":"An endpoint is a specific address on a backend that does one defined thing. One address handles fetching a list of products. A different address handles submitting a new order. A third handles logging in. Each endpoint is identified by two things: its path (the address, like `/api/products`) and its method (the verb that names what kind of action is being performed). GET means fetch something without changing it. POST means send data to create or trigger something. PUT or PATCH means update something that exists. DELETE means remove it. The combination of method and path is the full instruction: GET `/api/products` means \"give me the product list\"; POST `/api/products` means \"create a new product\".\n\nThis grammar is how every frontend and backend in the world communicate. When you open your browser's network tab and watch traffic go by, what you are seeing is a list of methods and addresses. When you call an external API, you choose the method and address that the API documentation defines. When you build your own backend, you decide what addresses exist and what method each one responds to. Knowing this lets you read any API documentation, understand any error message (\"405 Method Not Allowed\" means you used the wrong verb), and design your own routes predictably.\n\nWhen you describe a backend feature to Claude Code (or your own AI assistant), name the endpoint explicitly: \"Create a GET endpoint at `/api/products` that returns all products from the database, filtered by category if a category query parameter is provided.\" The more precisely you describe the address, the method, the inputs, and the expected output, the better the generated code will match your intent. After the model writes the handler, call the endpoint directly — with a browser tab, a tool like Insomnia, or a short fetch call — and check that the response looks like what you specified.\n\nThe most common shortcoming in AI-generated endpoints is that they handle the happy path and nothing else. The query succeeds, the response is formatted, done. What is missing: what happens when the database returns no results (should that be an empty array or a 404?), what happens when a required field is absent from the POST body (an error, not a silent null), what status code is returned when the caller sends invalid input. Before you ship any endpoint the model writes, ask explicitly: \"What error cases can this handler hit, and what should it return for each?\" The model knows; it does not include them by default.","prerequisites":["what-an-api-is"]},"what-json-is":{"title":"What JSON is: the language servers use to talk to each other","capsule":"JSON is the text format that APIs use to send structured data — labelled values in a predictable shape: names, numbers, lists. It is not code; it does not run. Once you can read a JSON response, you understand what any API is saying and can describe to the model exactly what data you need.","canonicalBody":"JSON is the text format that APIs use to exchange structured data. It looks like this: `{\"name\": \"Alex\", \"age\": 32, \"active\": true, \"tags\": [\"admin\", \"beta\"]}`. It is not code — it does not run; it is just data with labels. An API response is almost always JSON: when your app calls a payment provider to check a transaction, or an address service to validate a postcode, what comes back is JSON. When your app sends data to a backend — a form submission, a new record — it usually sends JSON too. Reading JSON fluently means you can understand what any API is telling you.\n\nBeing comfortable with JSON removes a layer of mystery from most debugging. When an API call fails, the error is in the response body — which is JSON — and it tells you exactly what went wrong if you read it. When you are designing a database schema or a new API route, thinking in JSON shapes forces precision: what fields exist, what type each one is, which ones might be absent. A learner who can look at a JSON response and describe its structure — \"this is an object with a `data` field that contains an array of order objects, each with an `id` and a `status`\" — can specify to the model exactly what they need.\n\nClaude Code (or your own AI assistant) handles JSON fluently. When you describe data you want to extract from an API response — \"I want the user's name and their list of order ids\" — the model writes the parsing code. What helps is giving it the actual shape. The habit is: make one real call to the API, look at the actual JSON response, and paste the relevant part into the conversation before asking the model to write the handling code. \"Here is what the response looks like; write code that extracts X and Y\" produces more accurate code than \"write code to call this API and get X and Y\" without the example.\n\nJSON handling breaks in predictable ways the model rarely guards against by default. A field you expect might be `null`. A nested object might be absent entirely. An array might be empty. A number might arrive as a string. Every time the model writes JSON-parsing code, ask: \"What happens if any of these fields is null or missing?\" Without that guard, the code throws a hard-to-trace error the first time the API returns unexpected data — which it eventually will. Ask for null-safety and missing-key handling explicitly. Treat every external API response as a document that might be incomplete.","prerequisites":["what-an-api-is"]},"css-making-it-look-right":{"title":"CSS: making it look right — and why you won't write much of it","capsule":"CSS is the language that tells a browser how to display HTML: colours, fonts, spacing, layout. It is notoriously fiddly to hand-write. The model is better at CSS than most developers will ever be. Your job is to describe what you want, check the result in the browser, and catch what it misses: responsiveness, accessibility contrast, and focus states.","canonicalBody":"CSS is the language that tells a browser how to display HTML: the colour of the heading, the size of the text, the spacing between elements, how the layout changes on a small screen versus a large one. CSS does not change what is on the page — that is HTML — and it does not make anything interactive — that is JavaScript. It controls only appearance and layout. CSS is notorious among developers for being fiddly to write by hand: the rules interact in non-obvious ways, browser differences create inconsistencies, and making something look correct on a phone, a tablet, and a laptop simultaneously is genuinely complex work.\n\nThis is also why CSS is one of the areas where delegating to Claude Code (or your own AI assistant) genuinely pays off. The model is better at CSS than most developers will ever be in the time available to them. It knows flexbox, grid, responsive breakpoints, accessibility contrast ratios, and a dozen layout patterns by rote. The skill you need is not memorising CSS properties — it is being able to describe what you want precisely enough for the model to produce it, and being able to look at the result in a browser and say what is wrong.\n\n\"Make this calmer — less contrast, more white space.\" \"This spacing feels cramped.\" \"The heading is too large on mobile.\" \"This button doesn't look clickable.\" These are valid and useful CSS instructions. You do not need to know that `justify-content: flex-end` is the way to right-align a flex child, or that `prefers-color-scheme` is the media query for dark mode. You need to be able to describe the visual outcome you want and then open the browser — on the actual screen sizes that matter — and check whether the model achieved it. If something looks wrong, describe what is wrong and ask the model to fix it. This loop is fast. What you must not do is approve CSS you have not seen rendered in a real browser — it is text, and the only ground truth is what it draws.\n\nYou do need a small amount of literacy to direct and diagnose well — not flexbox and grid, but the handful of ideas you will reach for constantly. **Colour**: that colours are written as hex codes (`#3366ff`) or RGB values, that you can pick one from a colour wheel or sliders rather than guessing, and that you can hand the model a specific colour rather than \"make it blue.\" **Classes**: that a class is a reusable label attached to elements, and that elements sharing a class share a look — so if two subtitles look identical but you wanted them different, the fix is \"give this one its own class,\" and you can ask the model for exactly that. **Fonts and icon packs**: that these are added to a project deliberately — a font is loaded, an icon set is installed — so when you want a different typeface or a specific icon, you are asking the model to add a resource, not invent one. **Padding and margin**: the space inside and around an element — enough that you can open the browser's developer tools, point at a cramped pricing card, and say \"the padding under this is too small,\" which is a precise, fixable instruction. This is the literacy that lets you read a symptom and direct the cure: you are not learning to write CSS, you are learning to see what is wrong and say it clearly.\n\nThere are four things the model reliably omits or gets wrong in CSS, and you must ask about them before the first prompt, not after you see the output. **Responsiveness**: does it look right on a phone? Always say \"make sure this works on small screens too\" before asking for any layout CSS — retrofitting responsiveness after the fact is significantly more work than building it in. **Focus states**: when a user tabs to an interactive element, can they see which element is focused? The model often removes the default browser focus ring (because it looks ungainly) without replacing it with something visible, leaving keyboard and assistive technology users with no indication of where they are. **Colour contrast**: does the text have sufficient contrast against its background for someone with reduced colour vision? The model picks colours that look harmonious to a well-sighted reviewer and fail basic accessibility checks under a contrast analyser. **The CSS framework you are using**: if your project uses Tailwind, Chakra, or any utility or component library, say so before the first prompt. If you do not, the model invents its own approach, and the resulting CSS conflicts with or duplicates whatever your framework already provides — and the conflict is painful to unpick.","prerequisites":["html-the-structure"]},"javascript-making-it-do-things":{"title":"JavaScript: making pages interactive","capsule":"JavaScript is the language that runs in the browser to make pages respond — buttons that do things, forms that validate, data that appears without a full reload. It also runs on servers as Node.js. You direct it and verify the result; you rarely write it from scratch. The browser console is how you catch what the model got wrong.","canonicalBody":"JavaScript is the language that runs inside the browser to make pages respond. A button that reveals a dropdown menu, a form that shows an error before it submits, a list that updates after you add an item without reloading the whole page — all of this is JavaScript. JavaScript also runs on servers, as Node.js, which is why the same language appears in both the frontend and the backend of many web applications. If you are building anything interactive, you will encounter it.\n\nYou do not need to be fluent in JavaScript to build with Claude Code (or your own AI assistant), but you need to understand what it does so you can describe what you want and check whether you got it. The key mental model: JavaScript is event-driven. Things happen in response to other things. A button is clicked, so a dropdown opens. A form is submitted, so the data is sent and a confirmation appears. Data arrives from an API, so the list updates. If you can describe the trigger and the expected outcome — \"when the user clicks Submit, validate the email field; if it is empty, show an error message beneath the field; if it looks valid, send the form data\" — the model can write the code.\n\nThe habit is: describe the interaction precisely, then test it in the browser. Click every button. Try the error cases: submit the form with no input, with an invalid email, with an overly long string. Open the browser console (F12 or right-click → Inspect → Console) and look for red error messages — these are exceptions the JavaScript threw that your code did not handle. The model writes code that works when everything goes right. Your job is to find the cases where it does not.\n\nThere are four failure modes in AI-generated JavaScript that appear often enough to check for by default. First: missing error handling on fetch calls. When a network request fails — the server is down, the response is a 500 — code without error handling either silently produces wrong output or throws an unhandled exception. Ask the model: \"What happens if this fetch fails?\" Second: event listeners that fire multiple times. In component-based frameworks like React it is easy for the same listener to be attached on every render, meaning a click fires the handler two or three times. Third: code that assumes a DOM element exists. JavaScript that runs before the page has finished loading will throw a null reference error on the first line that tries to access an element. Fourth: no loading or error state in the UI. The model writes the happy path — data loads, it is displayed — but not the states between: what the user sees while waiting, and what they see if the request fails. Test each case deliberately.","prerequisites":["html-the-structure"]},"what-a-database-is":{"title":"What a database is: data that outlives the session","capsule":"A database is where data lives permanently — not in a browser tab, not in memory, but on disk. Without one, everything a user does disappears when they close the browser. Once your app needs data to survive a session or be shared, you need a database — and the schema you start with is expensive to change later.","canonicalBody":"A database is the place where data lives permanently. Not in a browser tab, which disappears when you close it. Not in memory, which resets when the server restarts. On disk, in a structured form, waiting to be read or changed. Without a database, everything your users do is gone the moment they leave — the note they wrote, the settings they changed, the item they added to their cart. With a database, that data persists: it is there when they return tomorrow, it can grow over time, and it can be shared between multiple users. The moment your app needs to remember anything across sessions or across users, you need a database.\n\nWhat makes a database more than just a file is that it is queryable. You can ask it for all orders placed in the last seven days, for all users who have not confirmed their email address, for the ten products with the highest sales this month. The database finds, filters, sorts, and combines this data efficiently — in ways that would be prohibitively slow if you tried to replicate them in application code by loading all the data and processing it yourself. This is what shapes how you design an application: put the data in the database and let the database do the work of finding and combining it. The design of the data — which tables exist, what columns they have, how they link to each other — is called the schema, and getting it roughly right at the start matters.\n\nClaude Code (or your own AI assistant) designs schemas and writes queries well. You describe your data: \"I need to store users, and each user can have many orders, and each order has multiple line items with a product id and a quantity.\" The model produces a schema and the queries to create, read, update, and delete records. What you provide is the intent: what data you need to store and what questions you will want to ask of it. The model then provides the structure. Your job is to think through the questions before you ask — not after — because the schema flows from the questions.\n\nSchema design mistakes are expensive to fix. Changing the structure of a database after data is in it requires migration scripts, careful sequencing, and in some cases downtime. The model designs a schema for the use case you describe; it does not automatically think about what you might need in six months. Before you accept a model-generated schema, ask: what other questions will I want to ask of this data later? Is there any data I will need that is not stored here? The model also reliably omits indexes — the internal structures that make queries fast. A query that runs in milliseconds against a development database with a handful of rows can take seconds against a production database with millions. Ask for indexes on columns you will frequently filter or sort by, before you ship, not after you see the slowdown.\n\nKnowing you need a database is a separate question from knowing where to put one, and the second question has a real answer that is not \"the one everybody uses in production\". A database can be a file sitting next to your code, something a company runs for you, or a server you run yourself — and the cheapest of those is a better first choice than it sounds.","prerequisites":["what-is-a-backend"]},"deploying-going-live":{"title":"Deploying: the difference between dev and production","capsule":"Deploying means putting your code on a computer real users can reach — not your laptop. Development and production are intentionally different environments: different credentials, different data, different behaviour under load. Understanding this gap is the difference between a project that works on your machine and one that works for everyone.","canonicalBody":"Deploying means putting your code on a computer that real users can reach. Your laptop is not that computer. It runs the development version of your app: isolated from the internet, using test data, configured with your personal settings, and never exposed to more than one user at a time (you). Production is different: a server hosted on infrastructure someone else runs, receiving real traffic, using real credentials, holding real data. The gap between \"it works on my machine\" and \"it works for everyone\" is exactly the distance between those two environments — and crossing it without understanding the difference is how things break at the worst possible moment.\n\nWhat matters is not the mechanics of deployment — those change with every platform — but the conceptual model: development and production are two separate environments, and they are supposed to be different. Production uses real API keys, not test keys that are free and safe to expose. Production holds real user data, not fixtures. Production has multiple users hitting it simultaneously, not just you doing one thing at a time. Production cannot be restarted mid-use without someone noticing. Every technical decision made during development has implications for what happens in production. The habit is to think about the production environment before you write the code, not after.\n\nFor most new projects the practical path is: pick a hosting platform suited to what your app needs, follow its getting-started guide, and the platform handles the server configuration. Claude Code (or your own AI assistant) can walk you through the steps for whichever platform you choose. What you supply is: what kind of app this is, what environment variables it needs in production, and what platform you are targeting. What the model provides is the configuration files and the steps. Your job is to check that the configuration matches your actual production requirements, not just that it matches the generic example in the documentation.\n\nThe model treats deployment as an afterthought and makes the same four mistakes with notable frequency. **Hardcoded local URLs**: `http://localhost:3000` baked into a fetch call that works in development and fails silently in production because the local port does not exist on the server. **Hardcoded file paths**: absolute paths like `/Users/yourname/project/uploads` that work on your machine and break on the Linux server that almost every hosting platform runs. **Missing environment variable handling**: code that reads `process.env.DATABASE_URL` with no error if the variable is absent, so the app starts up and quietly fails. **OS-specific assumptions**: path separators, case-sensitive filenames — things that work on Windows or macOS development machines and break on Linux production servers. Before shipping any deployment-adjacent code, search the diff for \"localhost\", any absolute file path, and any environment variable reference without a fallback or a startup check.","prerequisites":["what-is-a-backend"]},"tables-and-the-join":{"title":"Tables and the JOIN: how databases link related data","capsule":"A relational database stores data in tables — rows and columns, like a spreadsheet. Related data lives in separate tables linked by a shared id. A JOIN follows those ids to combine tables on demand. Each fact is stored once; everything that references it stays consistent automatically. The JOIN is the idea that makes relational databases powerful.","canonicalBody":"A relational database stores data in tables: rows and columns, exactly like a spreadsheet. A users table has one row per user, with columns for id, name, email, and so on. An orders table has one row per order. The connection between them is a shared id: each order row stores the id of the user who placed it. A JOIN is a database operation that follows that id and combines matching rows from both tables into a single result — so you can ask for a list of orders and get back, in one query, the order details and the placing user's name and email.\n\nThe reason data is split across tables rather than stored together in one big table is that the JOIN is the idea that makes data stay correct. If you stored a user's name on every order row, and that user changed their name, you would have to update every row — and miss any you forgot. By storing the name once in the users table and referencing it with an id, one update is enough and everything that JOINs to it is automatically current. The principle is: each fact lives in one place; anything that references it links by id. This is what \"relational\" means.\n\nClaude Code (or your own AI assistant) writes JOINs well. You describe what you want: \"Give me a list of all orders placed this month, with each order's total, the placing user's name, and the number of line items.\" The model writes the SQL or the ORM query with the appropriate JOINs. What helps is giving it your schema — the table names and column names — either by describing it or pasting the relevant part of the schema definition into the conversation. After the model writes the query, run it once directly (via a database client, a migration script, or the model's generated test code) and read the result. Does it return what you expected? Are there rows missing that should be there?\n\nThe most common AI-generated database performance problem is the N+1 query pattern: code that fetches a list of records with one query, then inside a loop makes a separate query for each record to get related data. One query to get a hundred orders, then a hundred queries to get each order's user name — 101 queries where one JOIN would do. It is imperceptible on a laptop with ten rows in development and can make a page unusable in production with a million rows. The model generates this pattern because it is the straightforward code to write: get the list, then for each item get the related data. Any time you see a database call inside a loop, that is the pattern — replace it with a JOIN before you ship. Ask the model: \"Can this be done in one query instead of one per row?\"","prerequisites":["what-a-database-is"]},"environment-variables-and-secrets":{"title":"Environment variables and secrets: the one rule you cannot break","capsule":"One absolute rule: API keys, passwords, and any sensitive value never go in your code and never get committed to Git. They live in a .env file that .gitignore keeps out of the repository. A committed secret is compromised forever. The model will not enforce this for you — you check.","canonicalBody":"This is a rule, not a lesson. **Secrets — API keys, database passwords, any credential that grants access to something — never go in your source code, and never get committed to Git.** That is the whole thing. If you remember nothing else, remember that.\n\nThe mechanism is simple. A secret goes in a `.env` file that lives only on your machine, and `.env` is listed in `.gitignore` so it can never be committed. Your code reads the value at runtime (`process.env.STRIPE_SECRET_KEY`) rather than containing it. `.gitignore` is also where you keep other things out of the repository that should not be there: large files, and local test data. In production, the same secret goes in your hosting platform's environment settings, not in the code you deploy.\n\nWhy it is absolute: once a key is committed and pushed, treat it as compromised — permanently. Automated bots scan public repositories continuously for key-shaped strings, and deleting the commit afterwards does not help, because anyone who cloned the repo (or any cache) still has it. The only safe response to a leaked key is to revoke it and issue a new one.\n\nClaude Code (or your own AI assistant) will not enforce this for you, and there are two specific things to watch. First, AI sometimes inlines a real-looking value directly in generated code — a placeholder like `sk_live_abc123` written into the file for \"illustration.\" Always confirm the code reads `process.env.NAME` and contains no actual key. Second, the model will not remind you to add `.env` to `.gitignore`; check that `.gitignore` is correct before your first commit on any new project, because the first push is when secrets go public.","prerequisites":["deploying-going-live"]},"scoping-what-to-build":{"title":"Scoping: the conversation before the first line of code","capsule":"The most expensive mistake in AI-assisted development is building the wrong thing in the wrong order. Scoping is the structured conversation that fixes the boundary before any code is written: what is the minimum that proves the idea, what is explicitly deferred, and what assumption, if wrong, would change the whole approach.","canonicalBody":"Scoping is the work you do before you write a single line of code or ask Claude Code (or your own AI assistant) to produce one. It is a structured conversation — with yourself, with a colleague, or with the model as a thinking partner — that answers three questions: what is the smallest thing that proves this idea works, what is explicitly not being built in this round, and what assumption, if wrong, would change the whole approach.\n\nThe reason scoping matters is the same reason it is easy to skip: the model can start generating code immediately, and generated code feels like progress. It is not always progress. Code written against an incomplete or misunderstood scope is work you will either throw away or spend significantly longer untangling. The model does not push back on an ambiguous brief. It interprets the task as described, fills gaps with assumptions, and produces something that satisfies the letter of what you said — which may not be what you meant. Discovering the mismatch after a day of building is more expensive than discovering it in a five-minute scoping conversation.\n\nThe output of scoping is a short written summary, not a formal specification: what you are building, what you are explicitly not building in this round (the deferrals), the single user action that would prove the core idea works, and any technical assumptions that need to hold for the approach to make sense. This summary is the input to your first Plan mode prompt. It keeps the model's plan focused on the right scope and gives you a clear reference if the model starts expanding scope during execution.\n\nThe discipline is recognising the scoping urge. Every time you feel the pull to just ask the model to start — to sketch something out, to \"see where it goes\" — that pull is the signal to scope first. Sketching with a model is fast, which makes it feel low-cost. The actual cost is the time you spend reviewing and correcting output built against an unclear brief, and the accumulated complexity of features added before the foundation was decided. Scope first: write the three questions down, answer them, then start.\n\nOne thing your scope decides that is easy to miss: where this thing has to live. A scope that never needs to remember anything, and that only you use, can stay in a chat window for its whole life — and deciding that on purpose is a different thing from drifting into it.","prerequisites":[]},"plan-then-act":{"title":"Plan then Act: the core loop for building with AI","capsule":"Every non-trivial task should be planned before it is executed. In Plan mode the model describes what it intends to do; you review and approve before it acts. This loop — plan, review, act — is the discipline that keeps AI-assisted development controllable. Approving without reviewing is the most common way large, hard-to-reverse mistakes happen.","canonicalBody":"The Plan→Act loop is the core operational discipline of AI-assisted development. Before Claude Code (or your own AI assistant) makes any change to your project — before it touches a file — you describe the task and ask the model to plan. In Plan mode the model does not execute; it explains. It tells you what it intends to do: what files it will change, what new code it will write, what approach it is taking and why. You read the plan, check that it matches your intent, and only then approve. The model acts on your approval, not on its own judgement.\n\nThe reason execution is not the first step is that it is much harder to reverse than planning. A model executing a well-described task can change twenty files in the time it takes you to read one. Changes to databases, deployed code, or tightly coupled modules are particularly hard to unpick. Reviewing the plan costs minutes; reviewing and correcting the output of a misaligned execution can cost hours. The sequence is: plan, then review, then act — not act, then review.\n\nReviewing a plan well is a skill, and it is not about checking syntax. The model's syntax is almost always correct. You are checking three things: does the plan match what you actually asked for, are there steps in the plan that seem more invasive or complex than the task requires, and are there concerns the plan does not address — edge cases, security implications, dependencies on things that have not been built yet. If you find any of these, push back in Plan mode before you approve. Asking \"why are you doing it this way?\" costs nothing in Plan mode. Undoing a large execution after the fact costs significantly.\n\nThe habit is: every non-trivial task starts in Plan mode. For small, isolated changes — a colour tweak, a wording fix — Act mode directly is fine. For anything that touches multiple files, changes data structures, modifies logic you care about getting right, or has any security or cost implication, plan first. The boundary is simple: if you would want to review a diff before merging it, you want to see a plan before you approve it.","prerequisites":["scoping-what-to-build"]},"reading-what-the-ai-did":{"title":"Reading what the AI did: the verification habit","capsule":"After the model acts, your job is to check the result, not trust it. Read the diff for unexpected changes, run the code, and look for the omissions the model reliably makes: error handling, edge cases, security. The model is fast and often right; verification is what keeps 'often' from becoming 'almost never'.","canonicalBody":"Verification is a habit, not an audit. You are not checking for syntax errors — Claude Code (or your own AI assistant) almost always gets the syntax right. You are checking three things: that the code does what the plan said it would do, that it handles the cases that matter (not just the happy path), and that it does not contain the omissions the model makes with notable regularity.\n\nThe first part of verification is reading the diff — the list of what changed and how. Most tools show you this immediately after execution. Look at each changed file and ask: does this change do what the plan described? Are there changes to files you did not expect to be touched? Are there deletions of code you did not authorise? A model that was asked to add a feature and quietly removed an existing one to make room has made a scope decision that was not yours to make. Reading the diff before running the code takes minutes and catches these early.\n\nThe second part is running it. This sounds obvious but is the step most often skipped when code looks plausible. Run the code. Use the feature with real or realistic inputs. Try the case that should work and confirm it works. Then try the cases that should fail gracefully — an empty input, a missing required field, a network call that returns an error — and confirm they fail gracefully rather than crashing or producing wrong output silently. The model's happy path is almost always correct. The edge cases are where the model's assumptions are revealed.\n\nThe third part is looking specifically for the omissions. For most features, the same things are reliably absent from AI-generated code: error handling on async operations (what happens when a fetch fails or a database query throws), input validation before data reaches a database or external service, and any logging that would tell you what actually happened when something goes wrong in production. These are not obscure requirements — they are standard for production code. If you do not find them in the code, ask the model to add them. It knows how; it does not include them by default. Your confidence in the output is the honest test: if you cannot give it a 7 out of 10 or better — \"I understand what this does well enough to defend it\" — you need to understand it more before you approve it.","prerequisites":["plan-then-act"]},"documenting-as-you-go":{"title":"Documenting as you go: project memory that survives the chat","capsule":"An AI coding assistant has no memory between sessions. Decisions made, the reasons behind them, and the current project state live only in your files and docs. Documenting as you go — why a decision was made, what was deferred and why — is what makes the next session coherent and keeps the project recoverable when something breaks.","canonicalBody":"Claude Code (or your own AI assistant) has no memory between sessions. Each session starts fresh: no recollection of previous conversations, no understanding of decisions made last week, no awareness of the current state of the project unless you tell it. Everything the assistant \"knows\" about your project is what you put in front of it at the start of each session. If your only record of previous decisions is a chat history, and that chat history is long or gone, your next session starts from reconstruction — which is slow, error-prone, and often incomplete.\n\nDocumentation in an AI-assisted project is not a formal specification. It is project memory: the running record of what the project is, what decisions were made and why, and what has been deliberately deferred. The minimum useful documentation is three things: a brief current-state description (what the project does today, not what it will eventually do), a decisions log (what was chosen and why the alternatives were not), and a gaps list (what is not built yet, what was explicitly deferred, what is known to be incomplete or brittle). This documentation is the first thing you paste into a new session. It is context, not ceremony.\n\nThe model can help produce documentation. After a session, describe what was built and decided; the model can draft the update. What you provide is the facts; what the model produces is the prose. You edit for accuracy — especially for the why, which the model cannot supply because it does not know your reasoning — and for anything the model has embellished beyond what actually happened. The important thing is that you read it, verify it, and keep it current. Documentation that is wrong is worse than no documentation: it gives the model confidently incorrect context.\n\nThe compounding effect is real. A project documented as it grows is recoverable from any setback — a broken session, a wrong turn, a gap of weeks. But the habit has two AI-specific traps, and both make the documentation actively wrong. The model will cheerfully write docs that describe what the code was supposed to do, not what it actually does — it is summarising its own intent, not reading the result. Stale docs are worse than none. They get believed. The model also will not read your documentation unless you put it in front of it. A decisions log nobody feeds back into the next session is a diary, not project memory. The fix for both: point the model at the actual code, ask it to document what is there, then read the result against the code yourself before you commit it.","prerequisites":["plan-then-act"]},"context-and-cost":{"title":"Context and cost: what you are actually paying for","capsule":"Every AI model request has a cost and a limit on how much it can see — the context window. Most cost comes from re-sending the same large files on every turn. Understanding context helps you keep tasks focused, avoid patterns that make cost balloon, and know when a fresh session beats a drifting old one.","canonicalBody":"When you make a request to Claude Code (or your own AI assistant), the cost is not \"thinking time\" in the way consulting is billed by the hour. You are paying, roughly, for the volume of text the model processes in a single request: everything you send (your message plus all the files the tool attaches automatically) plus everything it generates (its response). This total is the context. Large context costs more per turn. A session that includes dozens of files re-sent on every exchange becomes expensive quickly — not because the model is doing more complex work, but because it is processing more text.\n\nThe context window is also finite. Every model has a maximum size for a single request; beyond that limit it cannot process everything it has been sent. Long sessions that accumulate conversation history, large tool outputs, and many attached files eventually approach or hit this limit. When that happens, the model either truncates silently (dropping earlier context without telling you) or refuses the request. The practical consequence: a long, drifted session is not just expensive — it is often less accurate, because the model is working from an increasingly incomplete picture of what was decided earlier.\n\nThe patterns that make cost balloon are knowable and avoidable. Sending the same large files on every turn — complete database schemas, long generated outputs, log files, full codebases — is the most common one. Another is asking for changes to many files in a single request: broader scope means more context, more generation, and a harder review. A third is not ending sessions when the task is complete and instead continuing to add tasks to the same session until it has accumulated hours of history. Each of these has a straightforward fix: attach only the files the current task needs, keep tasks narrow, and close the session when the task is done.\n\nStarting a fresh session for each new task is the single most effective cost guard — previous session history is not lost, it lives in your files and your documentation, and a fresh session starts with exactly what the new task needs. But cost is not the reason this matters most. Context exhaustion is not announced. It degrades quality silently and gradually: the model starts contradicting a decision it made earlier in the same session, re-suggests something you already rejected, or forgets a constraint you stated forty messages ago. It is easy to read this as \"the AI got worse\", or worse, as \"I am bad at this\" — neither is true. The tell is repetition and contradiction, not an error message. When you see it, do not push harder. Start fresh, and hand the new session a short summary of where things stand.","prerequisites":["plan-then-act"]},"when-it-breaks":{"title":"When it breaks: reading an error and asking a sharper second question","capsule":"Something breaks — an error message, a fix that does not work. This is normal, not a sign you did something wrong. Find what changed last, paste the whole error to the model, and ask a sharper second question if the first fix fails. After two failed attempts, stop, revert, and ask it to explain the cause first.","canonicalBody":"An error message is not a rejection. It is the most specific piece of information you will get all day. Most of it is noise. One or two lines carry the real signal: what went wrong, and where. On the first pass, find the actual message and find the file and line it points to. Ignore the rest of the stack. You can come back to it later if you need to.\n\nThe real skill is isolation: what changed between the last time this worked and now. Almost every break in a beginner's project is the very last thing you touched. Find that thing before you ask for help, and a five-minute fix stays a five-minute fix. Here is the part worth saying plainly: things breaking is not a sign you are doing this wrong. It is the normal texture of the work. Experienced people break things constantly, all day, every day — they are just faster at finding the last thing that changed.\n\nWhen you ask Claude Code (or your own AI assistant) for help, paste the whole error — not a summary of it, not \"it's not working\". Add what you were doing when it happened and what you changed just before. The model reads a stack trace far better than most people ever will; it just cannot see your last few minutes unless you tell it. If the first fix does not work, do not just ask again. Say what you tried, what happened instead, and what you now think is going on. That sharper second question is the whole skill.\n\nWatch for this: the model will always hand you a confident fix, even when it has no idea what is wrong. It will not say \"I don't know\" — it will guess plausibly, and a plausible wrong guess changes code that was not broken, so now two things are wrong instead of one. The tell is fixes that get bigger and stranger with each attempt, or that start rewriting things nowhere near the actual error. After two failed attempts, stop. Go back to your last save-point — the git-tracking-your-work habit — describe the problem fresh, and ask the model to explain the cause before it proposes anything. And if it still is not moving, walk away for a while — that is real engineering advice, not giving up.","prerequisites":["plan-then-act"]},"how-do-you-know-it-works":{"title":"How do you know it works? Verification, not test frameworks","capsule":"Checking that something works means deciding in advance what \"working\" looks like, then trying it — including the cases you would rather not think about: empty input, the wrong file, a field left blank. \"It ran without an error\" and \"it did the right thing\" are different claims. Build the habit of three cases: normal, empty, and shaped wrong.","canonicalBody":"Checking a thing works means deciding, in advance, what \"working\" actually looks like — then trying it. Not just the case you expect to happen, but the ones you would rather not think about: empty input, the wrong file, a field left blank, the same action done twice in a row. If you only ever try the case you already know works, you have not really checked anything.\n\nThe judgment is choosing which cases actually matter for your project — that is knowledge Claude Code (or your own AI assistant) does not have, because it does not know your data or your users. The habit worth building is three cases, every time: the normal case, the empty case, and the case shaped wrong. Hold onto this distinction, because it is where the expensive mistakes hide: \"it ran without an error\" and \"it did the right thing\" are not the same claim. Code can run cleanly and still be wrong.\n\nThe model will write the checks for you — real automated tests if you ask for them, or simply a list of cases worth trying by hand. You own the list of what actually matters here; the model owns the mechanics of checking it. Before you accept a new feature, ask directly: \"what could go wrong with this, and how would I check each one?\" Read its list, and decide which of its answers you actually care about — not all of them will be.\n\nTwo things to watch for. First: a check written from the same brief that produced the code shares the same blind spots — it confirms the model built what it thought you meant, not what you actually meant. A check passing is not evidence you got what you wanted; it is evidence the model was consistent with itself. Second, the familiar failure: the model checks the case where everything goes right, and stops there — the same happy-path gap named in endpoints-and-requests and javascript-making-it-do-things. The counter-move for both: bring one real, awkward example from your own data — the row with the missing field, the name with an apostrophe in it — and ask the model what happens to it. That one case, from you, is worth more than a dozen the model invented on its own.","prerequisites":["reading-what-the-ai-did"]},"reading-an-unfamiliar-codebase":{"title":"Reading an unfamiliar codebase: the first hour with code you did not write","capsule":"You inherited a codebase you did not write — a team's tool, a project you are joining partway through. You do not read it front to back like a book. Find one entry point and follow it, letting the model summarise what you point it at — but check every summary against the real lines it is based on.","canonicalBody":"You inherited a codebase: a repository someone else wrote, a tool your team already has, a project you are joining partway through. The instinct is to open every file and try to read the whole thing before you touch anything. Do not do that. A codebase is not a book — there is no cover-to-cover order that makes sense, and most of it is irrelevant to whatever question actually brought you here. The way in is to find one entry point — the file that runs first, the route a request hits, the button that starts the flow you care about — and follow it.\n\nThe skill is not reading faster. It is deciding what to read at all. Before you open a second file, know what question you are trying to answer: what does this button do, where does this number come from, why does this page look different in production. Everything not on the path to that answer is noise you can ignore for now. A codebase you are new to always looks bigger than the part of it that matters to your actual question — most of the fear people feel here is really the fear of not knowing what to skip.\n\nThis is the one place Claude Code (or your own AI assistant) is genuinely transformative, and it is worth saying plainly: it reads faster than any person, and it will summarise a file, a function, or a whole module the moment you point it at one. You own the question. The model owns the reading. Ask it directly — \"what does this file do,\" \"where is this value set,\" \"walk me through what happens when this function runs\" — and let it do the scanning you would otherwise do by hand.\n\nThe nasty surprise: the model will confidently explain code it has only partially seen, and a summary of a large file is a plausible reconstruction, not a reading — it fills gaps with the common version of a pattern it recognises, which may not be the version actually in front of it. Ask it to quote the exact lines a claim is based on before you trust the claim. A summary you cannot trace back to real lines of code is a guess wearing the shape of an answer.","prerequisites":[]},"tracing-how-something-works":{"title":"Tracing how something works: from what you see back to the code that causes it","capsule":"Something in a codebase you did not write behaves a certain way — a button, a report, a number that looks wrong — and you need to know why. Tracing follows that behaviour back to the code that causes it. Pick a thread narrow enough to finish; the model follows fast, but only you know when you reach the source.","canonicalBody":"Pick one thing you can actually see happen. A button that does something. A report that shows a number. A page that behaves oddly. Follow it from that visible behaviour back to the code that causes it. Not the whole feature — one thread. What happens when I click Save. Why does this total look wrong. Where does this error come from. The skill is choosing a thread narrow enough to actually finish in one sitting. A thread too broad never resolves. It just grows more threads.\n\nYou are looking for where the behaviour is actually decided — the line, the condition, the query — not just where it shows up on screen. Following a thread usually means moving backwards: the screen, to the function that filled it, to the function that called that one, to wherever the value first came from. You know you have reached the bottom when you hit something that is not itself made by more code — a stored value, a setting, an answer from outside the app.\n\nClaude Code (or your own AI assistant) is very good at exactly this kind of following. \"Where does this function get called from.\" \"What happens between this button and this database write.\" \"Trace this value back to where it is set.\" Give it the concrete behaviour and let it walk the chain. What stays yours is choosing which behaviour to trace, and knowing when the chain has actually reached its source rather than when you have simply run out of patience.\n\nThe nasty surprise: for a pattern the model knows well, it will happily describe a call chain that sounds right and does not exist in this codebase. It fills the gap with the version it has seen a thousand times elsewhere, not the one actually in front of it. It also traces code, and only code — a setting, an environment variable, or data sitting in a database is usually invisible to it unless you show it directly. \"Why does this behave differently in production\" is very often not a code question at all, and a trace that never looks outside the source files will confidently miss the real answer.","prerequisites":["reading-an-unfamiliar-codebase"]},"changing-code-you-did-not-write":{"title":"Changing code you did not write, safely","capsule":"You need to change code you did not write and do not fully understand. Prove you understood it first: make the smallest change that tests your theory, confirm the behaviour moves as expected, then widen it. Direct the model narrowly and commit first — an unreviewed diff in unfamiliar code is the fastest way to break something you cannot see.","canonicalBody":"The safest way to change code you did not write is to prove you understood it before you trust yourself with anything bigger. Make the smallest change that tests your theory — flip one value, comment out one line, add one log statement — and confirm the behaviour moves the way you expected. If it does not move at all, or moves in a way you cannot explain, you have not found the real cause yet, and a bigger change built on that guess will not work either.\n\nThis is slower than jumping straight to the fix you think you need, and that is the point. In code you did not write, your model of how it works is a guess until it is tested. One small, confirmed change turns the guess into a fact you can build on. Only once the small change behaves as predicted do you widen it into the real fix.\n\nDirect Claude Code (or your own AI assistant) to make one narrow, named change — not \"fix this\", but \"change this one condition, and nothing else.\" Before you ask for anything non-trivial, commit the current state first, the save-point habit from git-tracking-your-work: if the change goes wrong in code you do not fully understand, you want a clean point to return to, not a diff you have to unpick by hand.\n\nThe nasty surprise: asked to change one thing in unfamiliar code, the model will often tidy, rename, reformat, or \"improve\" adjacent code nobody asked it to touch — and the diff that comes back has your real change sitting among forty cosmetic ones. In code you do not fully understand, you cannot tell which of those forty might have been load-bearing. Ask explicitly for the minimal diff, and refuse drive-by refactors. Then review the diff itself, line by line — not a description of what it does.","prerequisites":["tracing-how-something-works"]},"when-to-leave-the-chat":{"title":"When to leave the chat, and when to stay","capsule":"Six questions decide whether your project needs to move onto your own computer: does it need to remember things, keep a secret, serve more than one person, run while you sleep, outgrow one file, or stop forgetting what you already fixed. If none of them is a yes, stay where you are. That is a real answer.","canonicalBody":"You have been building in a chat window. It works. Something in you says the next step is to move it onto your own computer, into a proper folder, with proper tools. Before you do that, it is worth asking whether you need to.\n\nSix questions decide it. Any one yes is enough.\n\nDoes it need to remember things between sessions? Not \"remember\" as in the chat recalls what you said. Remember as in a person types something today and it is still there next week. That needs somewhere to store it, and a chat window has nowhere.\n\nDoes it need to keep a secret? A key is a password that lets your code use somebody else's service. If your project needs one, it cannot live in a page a stranger can open, because anything the page holds, they can read.\n\nIs there more than one person? Or one person on two devices? The moment two people must see the same thing, that thing has to live somewhere they can both reach.\n\nDoes it need to run when nobody is looking? Something that checks an inbox each morning, or sends a reminder on a Friday, has to run without you starting it.\n\nHas one file stopped being enough? Not because someone told you real projects have many files. Because you cannot find anything any more, and every change breaks something else.\n\nAre you fixing the same thing twice? A conversation only holds so much. When it forgets an earlier decision and undoes it, you are paying for that forgetting.\n\nNow the answer nobody gives you. If every one of those is a no, stay where you are. A tool that turns something you paste in into something you copy out, that only you use, that nobody needs tomorrow — that project is finished. It does not need a folder or a database. It is not a lesser thing for living in a chat window. It works, which is the only test that matters.\n\nThe expensive mistake here is not staying too long. It is leaving too early. Setting up your own machine takes an afternoon at best, and for many people it takes a few evenings. Spend that on a project that never needed it and you spend your enthusiasm on plumbing. People who quit rarely quit because the idea was bad. They quit during setup for a thing that was already working.\n\nThere is a second cost, and it is worth knowing before you start rather than halfway through. Chatting is free. An assistant that runs on your own computer and edits your files is not — it needs a paid plan, and the price is on the website of whoever makes the one you pick. That is not a reason to avoid it. It is a reason to check the six questions honestly first, because paying monthly to keep plumbing running for a project that was finished is a worse feeling than the money.\n\nPut the two costs together and the answer sharpens. Staying is free, takes no afternoon, and costs you nothing if you are wrong about it. Leaving costs a subscription and a weekend, and is only expensive if you did not need to.\n\nSo use the six questions as a gate rather than a milestone. Ask them again in a month. A no today is not a no forever, and moving later costs you almost nothing you have not already learned.","prerequisites":["scoping-what-to-build"]},"moving-to-your-own-machine":{"title":"Moving onto your own machine","capsule":"A development environment is just your own computer running the same pieces a server would, so you can change them and see what happens. A chat cannot do this: it has no folder, no running program, and nothing that survives the tab closing. Getting the tool is one download. Expect the rest to take an afternoon, and to be fiddlier than the feature you build next.","canonicalBody":"A development environment sounds like a piece of software you install. It is not. It is a description of your own computer once it is running the same pieces a real server would run: the language your code is written in, the tools that fetch other people's code, a place on disk where your project lives, and a way to start it and watch it work.\n\nThat is the whole idea. Your machine becomes a small, private copy of the place your project will eventually live. You change something, you run it, you see what happens. Nobody else sees any of it. Nothing you break is public.\n\nThe reason a chat window cannot do this for you is worth being precise about, because it is not a limitation anyone will fix. A chat has no folder. There is nowhere for a file to sit. It has no running program, so nothing can be started and left going. And it has nothing that survives the tab closing. It can write you excellent code. It cannot hold it.\n\nSo the move is not an upgrade to a better chat. It is a change in where your project lives. Up to now your project has been a description — words, and code you copy out. After the move it is a thing on a machine: files in a folder, a program that runs, a version of a language, maybe a database listening on a port. That is a real shift, and it is why this step feels bigger than the ones before it.\n\nGetting the tool itself is the easy part, and it is worth saying so, because people brace for the wrong thing. Claude Code (or your own AI assistant) is one download. It comes as an app with a window, so there is nothing to type to install it and no separate language to set up first. You open it, you point it at a folder, and it is working. One thing to check before you start: running it on your own machine needs a paid plan, where the chat you have been using so far did not.\n\nThere is also a version that runs in a terminal, if you would rather work that way. It is the same tool. Start with the app unless you already know you want the other one.\n\nDirecting it through this part works, with one adjustment. Tell it what your computer is first. Which operating system, what you already have installed. Something that has to guess will give you instructions for the most common setup it has seen, which may not be yours, and the errors that follow will look like your fault. Ask for one step at a time and check each one before the next. The check is simple and always the same: run the thing, read what it prints, and say what you actually see. \"It says command not found\" is far more useful than \"it did not work\".\n\nNow the part nobody warns you about. The setup afternoon is often longer than building the first feature, and that is not a sign you have done something wrong. It is the normal shape of this step, for everybody, including people who do it for a living.\n\nAnd notice where the afternoon actually goes, because it is not the download. It goes on the folder you cannot find again, the first run that stops with a message you have never seen, and the twenty minutes of not knowing which of five suggestions to try. An app with a window removes the typing. It does not remove that.\n\nThe errors you hit here are almost never about your ability. They come from three things that stay invisible until they break. Paths, which are how your computer finds a program by name. Versions, where you have one number and something expects another. And permissions, where the computer refuses to let you change something for a reason it explains badly. None of those are concepts you failed to understand. They are plumbing, they are fiddly for everyone, and hitting them means you are exactly where you are supposed to be.\n\nIf you have been building happily in a chat and this step suddenly feels like a wall, that is the common experience, not a private one. Take it one line at a time, keep the errors, and stop for the day when you need to. The folder will still be there.","prerequisites":["when-to-leave-the-chat"]},"the-prototype-is-a-sketch":{"title":"Your prototype is a sketch, not a foundation","capsule":"The one big file a chat gave you is not a design choice — it is just how chat tools hand over code. What is valuable in it is the decisions: the shape of the data, the flows you tested on real people, the bits that felt right. Keep those, rebuild the structure, and know which is which.","canonicalBody":"You have a prototype. It probably arrived as one long file, and it probably works. Now you want it to be a real project, and the obvious move is to tidy this file up: split it into pieces, put it in folders, make it proper.\n\nThat instinct is usually the wrong one, and it is worth understanding why before you spend a weekend on it.\n\nStart with what that file actually is. It is one file because chat tools hand back one file. Nobody decided that. There is no design in it to preserve. Ask for a working thing in a chat window and you get a single block you can paste somewhere and run, because that is the only shape a chat can deliver.\n\nWhat is valuable in your prototype is not the code. It is the decisions baked into it. You worked out what pieces of information the thing needs to hold. You settled on an order of steps that made sense. You showed it to somebody and watched where they hesitated, and you changed it. Some part of it felt right and you kept it. Every one of those is real knowledge, and none of it is written down anywhere except in that file.\n\nSo the move is usually to rebuild, guided by the prototype, rather than to reshape the prototype. You keep the decisions and you let the structure go. Knowing which is which is the actual skill here, and it is worth being slow about. A decision is anything you would defend to somebody else. The structure is everything you would shrug at.\n\nDirecting that rebuild well is mostly about what you say up front. Hand over the prototype as a reference, not as a starting point. Then say what has to stay true: this is the information it holds, these are the steps a person goes through, this bit must behave exactly like this because I tested it. Then let Claude Code (or your own AI assistant) choose the structure. It is good at structure and you have no reason to have opinions about it yet.\n\nThe trap is asking for something that sounds simpler. \"Split this file up\" seems like a small, safe request. It is neither. Without being told what must still be true, the model reorganises your code into a perfectly tidy set of folders that does something subtly different from the thing you tested. The obvious parts still work, so nothing looks wrong. The difference is usually in an edge you found by accident weeks ago and never wrote down — and you will not notice for a fortnight, by which point you have built on top of it.\n\nWhich gives you the guard. Before any restructuring, write down what the thing does that matters, in plain sentences. Then check the new version against that list by using it, not by reading it. If you cannot write the list, you are not ready to rebuild yet, and the prototype is still teaching you something.","prerequisites":["moving-to-your-own-machine"]},"directing-a-coding-agent":{"title":"Directing Claude Code without handing over the keys","capsule":"Claude Code can read, write and run things in your project folder, which makes it far more useful than a chat and far easier to lose track of. Read the diff before you say yes. Never approve a command asking for your password on trust. Set up .gitignore before the first commit, not after.","canonicalBody":"Claude Code (or your own AI assistant) is different from a chat in one way that changes everything. It runs in your project folder, and it can read your files, change them, and run commands on your machine. You stop copying code across and start approving changes. That is a genuine jump in what you can do, and it is also the moment you can start losing track of your own project.\n\nThis is about the brakes. None of it is about distrusting the tool. It is about staying the person who knows what is in the folder.\n\nRead the diff before you say yes. A diff is just the before-and-after of a change, with the removed lines and the added lines shown together. You are not reading it to check the syntax. You are checking three things. Is it touching only the files you expected? Is it deleting something you wanted to keep? Does the shape of what it did match what you asked for? That is a ten-second read most of the time, and it is the single highest-value habit in this whole topic.\n\nThere is one command you never approve on trust. Anything asking for your password, or starting with a word that means \"do this as the administrator\", is asking for permission to change your computer rather than your project. Sometimes that is genuinely needed. But it is always the moment to stop and ask why, in plain words, before you say yes to it — whether saying yes means clicking a button or typing a letter. A good answer is specific: it needs to install this tool in this place. A vague answer is your signal to say no and ask again.\n\nSet up two files before your first commit, not after. A commit is a saved point in your project's history. One of the files is called .gitignore, and it is a list of things that must never be saved into that history. The other holds your secrets — keys and passwords — and it goes in that list. Do this in the wrong order and a key ends up in your project's history permanently. Deleting the file afterwards does not remove it, because history is the point of history. Fixing that properly is a genuinely annoying job, and everyone who has done it once does it in the right order forever after.\n\nThere is a mode that stops asking you to approve each change. It is reasonable in narrow places: a batch of small mechanical edits you have already agreed to, in a project where every change is saved and reversible. It is not reasonable as a default, and it is at its worst exactly when you are tired and it is going well.\n\nMoney is real here too. An agent working through a task keeps sending your project back and forth, and a long run costs more than a short one. A focused session on one task should feel like a small amount. If a number surprises you, that is usually a task that was too big, not a tool that is expensive.\n\nWhich brings us to the actual thing that goes wrong, because it is not the dramatic one. Nobody's project gets destroyed by one obviously bad command. What happens is quieter. It is going well, so you stop reading. You approve fifteen changes in a row, all of them plausible, none of them read. Two hours later something is broken and you open the folder and do not recognise it. Now you cannot review it, because you never saw it being built. You cannot debug it, because you do not know what is where. And you are left trusting the thing that wrote it to explain it, which is the one position this whole approach exists to keep you out of.\n\nThe defence is small tasks, one at a time, checked. Ask for one change. Read the diff. Run it. Save it. Then ask for the next. It feels slower and it is not, because the alternative is a folder you have to re-learn from scratch.","prerequisites":["moving-to-your-own-machine","reading-what-the-ai-did"]},"where-your-data-lives":{"title":"Where your data should actually live","capsule":"You have three real options: a database that is just a file on your machine, a hosted one somebody else runs, or a full server running in a container on your laptop. For a first project, start with the file. Not because it is a lesser choice, but because it keeps the decision cheap to change later.","canonicalBody":"\"Set up a local database\" sounds like one step. It is five: install it, get it running, connect to it, create the tables, and put something in. Each of those has its own way of going wrong, and none of them is the thing you actually wanted to build. It is worth knowing that before you start, because a lot of people's enthusiasm ends somewhere in the middle of it.\n\nYou have three real choices. They are genuinely different, and the differences are about cost to you rather than quality.\n\nThe first is a database that is just a file sitting next to your code. SQLite is the one everybody uses. There is nothing to install and nothing to start — your code opens the file the way it would open any other. It is a real database, with real tables and real queries, and it is not a toy. It happily handles far more than a first project will ever ask of it. What it does not do well is many people writing at the same moment, and it does not sit on a server other machines can reach.\n\nThe second is a hosted database. Somebody else runs it and gives you a connection string, which is one line of text holding the address and the password. Several companies give you a small one free. You install nothing, it works from any computer you sit at, and backups are somebody else's job. The costs are that it needs the internet, that the free tier has limits you may meet, and that your data now lives with a company you should check the terms of.\n\nThe third is a full database server running on your own machine, usually inside a container. A container is a way of running a program in its own sealed box so it cannot disturb the rest of your computer. This is the most faithful copy of what a real deployment looks like, which is a genuine advantage later. It is also the most moving parts by a wide margin. The container tool has to be installed and running. The database inside it has to be configured. Something has to connect the two to your code. On Windows in particular, this is where a lot of people stop.\n\nSo here is the answer rather than the menu. For a first project, use the file. Start with SQLite.\n\nThat is not a compromise recommendation, and the reason matters more than the recommendation does. It is about how expensive the decision is to reverse. If you have not written anything that depends on one specific database, moving from one to another is a small job — you change how your code connects and you copy the data across. If you have written a lot of queries in one database's own dialect, or leaned on features only it has, moving is a rewrite.\n\nWhich means starting simple is not \"good enough for now\". It is the option that keeps you able to change your mind. You will know far more about what your project needs after a month of using it than you do today, and the cheap choice is the one that lets that knowledge count for something.\n\nTwo things to say to Claude Code (or your own AI assistant) when you get there. Ask it to keep your data access in one place rather than scattered through your code, so that changing databases later touches one file. And when it suggests running a database in a container because that is what production looks like, say what you actually want: the simplest thing that stores my data, and tell me later when I have outgrown it.","prerequisites":["what-a-database-is","moving-to-your-own-machine"]}};
/* CONCEPT_BODIES:end */
(async () => {
  const fail = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const learnerId = String(Inputs.learnerId || '').trim();
    const conceptId = String(Inputs.conceptId || '').trim();
    const who = await DOOR.learner(learnerId);
    if (!who) return fail('There is no learner with the id "' + learnerId + '". learnersForLessons lists them.');
    const { steps } = await DOOR.livePath(learnerId);
    const at = DOOR.stepFor(steps, conceptId, who.name);
    if (at.why) return fail(at.why);
    const concepts = await DOOR.q('Concept', {});
    const titleOf = Object.fromEntries(concepts.map((c) => [c.conceptId, c.title]));
    const body = CONCEPT_BODIES[conceptId] || null;
    const [pub, dr, elsewhere] = await Promise.all([DOOR.published(learnerId), DOOR.drafts(learnerId), DOOR.fieldsElsewhere(learnerId, conceptId)]);
    const others = (await DOOR.q('Lesson', { conceptId: { equalTo: conceptId } })).filter((l) => l.learnerId !== learnerId);
    const copyFrom = [];
    for (const id of [...new Set(others.map((l) => l.learnerId))]) {
      const o = await DOOR.learner(id);
      if (o) copyFrom.push({ learnerId: o.learnerId, name: o.name, projectName: (o.ctx && o.ctx.projectName) || null });
    }
    const p = pub[conceptId];
    const d = dr[conceptId];
    Outputs.context = {
      learner: { learnerId: who.learnerId, name: who.name },
      project: who.ctx
        ? { name: who.ctx.projectName || null, problemStatement: who.ctx.problemStatement || null, savedAnswers: who.ctx.facts || {}, version: who.ctx.version || 1 }
        : null,
      step: { position: at.step.position, of: steps.length, status: at.step.status, rationale: at.step.rationale || null },
      path: steps.map((s) => ({ position: s.position, conceptId: s.conceptId, title: titleOf[s.conceptId] || s.conceptId, status: s.status })),
      concept: {
        conceptId,
        title: titleOf[conceptId] || (body && body.title) || conceptId,
        capsule: body ? body.capsule : null,
        canonicalBody: body ? body.canonicalBody : null,
        prerequisites: body ? body.prerequisites : [],
        note: body ? null : 'This concept has no teaching body in the course corpus. Write from its title and the learner\'s project, and say so to the trainer.'
      },
      captureFieldsInUse: Object.entries(elsewhere).map(([field, inLesson]) => ({ field, inLesson })),
      lesson: {
        published: p ? { generationVersion: p.generationVersion, title: p.title } : null,
        draft: d ? { version: d.version, publishedVersion: d.publishedVersion || null, copiedFromAnotherLearner: !DOOR.blank(d.copiedFromLearnerId), previewPath: DOOR.previewPath(learnerId, conceptId) } : null
      },
      canCopyFrom: copyFrom
    };
    Outputs.done();
  } catch (e) {
    console.error('[dbt:lessonContext] stopped: ' + String((e && e.message) || e));
    fail('That did not finish, and nothing was half-saved that a second try will not put right. Try again.');
  }
})();
